useEffect(() => {
   const fetchUsers = async () => {
      try {
         // Gọi thẳng API vì Backend đã bỏ verifyAdmin
         const res = await fetch(`${BASE_URL}/users`, {
            method: 'GET'
         });

         const result = await res.json();

         if (res.ok) {
            // Backend của bạn trả về { success: true, data: users }
            // Nên ta lấy result.data
            setUsers(result.data || []);
         } else {
            setError(result.message || "Lỗi tải dữ liệu");
         }
         setLoading(false);
      } catch (err) {
         setError("Lỗi kết nối Server!");
         setLoading(false);
      }
   };

   fetchUsers();
}, []);
